(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.03+t*0.5)*8+Math.cos(my*0.025-t*0.4)*6;
  const w2y = Math.cos(my*0.028-t*0.45)*8+Math.sin(mx*0.022+t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.14,1.3,0.8],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*45,0.11,1.8,1.0],
    [200+Math.sin(t*0.7+6)*90,220+Math.cos(t*0.3+5)*60,0.05,2.8,1.15],
    [300+Math.cos(t*0.25+7)*80,30+Math.sin(t*0.85+2)*55,0.09,2.1,0.9]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.atan2(sy-sY,sx-sX);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    wS+=Math.sin(d*f*0.4+a*2-t*sp*0.8)*amp*0.5;
  }
  const act=aS/10,inh=iS/10,wave=wS/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.9))/3+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(Math.sqrt(sx*sx+sy*sy)*0.03+t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+(Math.sin(dist*0.08+ang*2-t*2.0)+Math.cos(dist*0.06-ang*5-t*1.8))*0.25;
  const cross=Math.sin(act*2.5+inh*1.8+wave*1.2)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+cross+wave*0.4)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-t*0.7)*Math.cos(sy*0.18+t*0.5)*0.3)*1.5)*0.3;
  const micro=(Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)+Math.sin((sx-sy)*0.3+t*2))*0.08;
  const v=(reaction*0.65+cell*0.25+micro*0.1)*0.5+0.5;
  const pal=[[5,12,45],[12,55,85],[18,110,120],[45,165,145],[140,200,120],[220,200,70],[230,150,60],[200,85,65],[160,50,80],[100,30,70],[50,20,60],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(wave)*0.1;
  const edge=Math.abs(reaction)>0.7?1.12:Math.abs(reaction)>0.5?1.05:1.0;
  const glow=Math.max(0,reaction-0.3)*0.15;
  return[Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)];
}
